import{_ as i,o as a,c as l,ao as o}from"./chunks/framework.cyfFUN0r.js";const p=JSON.parse('{"title":"Albums","description":"","frontmatter":{},"headers":[],"relativePath":"grindr-api/messaging/albums.md","filePath":"generated/grindr-api/messaging/albums.md"}'),s={name:"grindr-api/messaging/albums.md"};function t(n,e,d,r,c,u){return a(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="albums" tabindex="-1">Albums <a class="header-anchor" href="#albums" aria-label="Permalink to “Albums”">​</a></h1><p>Pressie albums are albums other profiles shared with you. <code>POST /v3/pressie-albums/feed</code> lists them in <code>sharedAlbums</code>; <code>albumViewable: false</code> marks a locked one, and <code>POST /v3/pressie-albums/feed/paywall/</code> returns blurred previews of locked albums. <code>profileFeeds</code> holds new content from those albums, one entry per profile, with <code>paywallStatus: PAYWALL</code> on locked entries.</p><h2 id="get-my-albums" tabindex="-1">Get my albums <a class="header-anchor" href="#get-my-albums" aria-label="Permalink to “Get my albums”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v1/albums</span></span></code></pre></div><p>Response:</p><ul><li><code>albums</code> — array of <a href="/grindr-api/messaging/albums#myalbum">MyAlbum</a></li></ul><h2 id="get-an-album" tabindex="-1">Get an album <a class="header-anchor" href="#get-an-album" aria-label="Permalink to “Get an album”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v2/albums/{albumId}</span></span></code></pre></div><p>Response:</p><p><a href="/grindr-api/messaging/albums#albumdetailsresponse">AlbumDetailsResponse</a></p><p>Errors:</p><ul><li><code>403</code> — if you don&#39;t have access to album or it doesn&#39;t exist</li></ul><h2 id="rename-an-album" tabindex="-1">Rename an album <a class="header-anchor" href="#rename-an-album" aria-label="Permalink to “Rename an album”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PUT /v2/albums/{albumId}</span></span></code></pre></div><p>Body:</p><ul><li><code>albumName</code> — string or <code>null</code></li></ul><p>Response:</p><ul><li><code>albumId</code> — integer</li><li><code>albumName</code> — string or <code>null</code></li></ul><h2 id="get-an-album-media-poster" tabindex="-1">Get an album media poster <a class="header-anchor" href="#get-an-album-media-poster" aria-label="Permalink to “Get an album media poster”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v1/albums/{albumId}/content/{contentId}/poster</span></span></code></pre></div><p>Response:</p><ul><li><code>blurredPosterUrl</code> — URL</li><li><code>posterUrl</code> — URL</li></ul><h2 id="record-view-of-an-album" tabindex="-1">Record view of an album <a class="header-anchor" href="#record-view-of-an-album" aria-label="Permalink to “Record view of an album”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v3/albums/{albumId}/view</span></span></code></pre></div><p>Response:</p><p>Empty.</p><p>Errors:</p><ul><li><code>403</code> — Repeated requests after invoking this endpoint on view ONCE albums cause HTTP status 403 Forbidden and <code>Action not permitted</code> error.</li></ul><h2 id="record-view-of-media-in-an-album" tabindex="-1">Record view of media in an album <a class="header-anchor" href="#record-view-of-media-in-an-album" aria-label="Permalink to “Record view of media in an album”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Repeated requests after reaching remainingViews=0 do not cause any errors.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v1/albums/{albumId}/view/content/{contentId}</span></span></code></pre></div><p>Response:</p><ul><li><code>remainingViews</code> — integer</li></ul><h2 id="get-info-about-profile-s-album" tabindex="-1">Get info about profile&#39;s album <a class="header-anchor" href="#get-info-about-profile-s-album" aria-label="Permalink to “Get info about profile&#39;s album”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v2/albums/shares</span></span></code></pre></div><p>Body:</p><ul><li><code>profileId</code> — long integer</li></ul><p>Response:</p><ul><li><code>profileId</code> — long integer</li><li><code>hasAlbum</code> — boolean</li><li><code>hasSharedWithMe</code> — boolean</li></ul><h2 id="get-albums-shared-by-a-profile" tabindex="-1">Get albums shared by a profile <a class="header-anchor" href="#get-albums-shared-by-a-profile" aria-label="Permalink to “Get albums shared by a profile”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v2/albums/shares/{profileId}</span></span></code></pre></div><p>Response:</p><ul><li><code>albums</code> — array of objects <ul><li><em>everything from <a href="/grindr-api/messaging/albums#albummin">AlbumMin</a></em></li><li><em>everything from <a href="/grindr-api/messaging/albums#albumexpiration">AlbumExpiration</a></em></li><li><code>profileId</code> — integer</li><li><code>content</code> — <a href="/grindr-api/messaging/albums#albumcontentmin">AlbumContentMin</a>, a single blurred preview content item</li><li><code>contentCount</code> — object <ul><li><code>imageCount</code> — integer</li><li><code>videoCount</code> — integer</li></ul></li></ul></li></ul><h2 id="create-an-album" tabindex="-1">Create an album <a class="header-anchor" href="#create-an-album" aria-label="Permalink to “Create an album”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v2/albums</span></span></code></pre></div><p>Body:</p><ul><li><code>albumName</code> — string or <code>null</code></li></ul><p>Response:</p><ul><li><code>albumId</code> — long integer</li><li><code>albumName</code> — string or <code>null</code></li></ul><p>Errors:</p><ul><li><code>402</code> — The account already has <code>maxAlbums</code> albums, see <a href="/grindr-api/messaging/albums#get-album-limits">Get album limits</a>.</li></ul><h2 id="delete-an-album" tabindex="-1">Delete an album <a class="header-anchor" href="#delete-an-album" aria-label="Permalink to “Delete an album”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DELETE /v1/albums/{albumId}</span></span></code></pre></div><p>Response:</p><p>Empty</p><p>Errors:</p><ul><li><code>403</code> — Repeated requests cause 403 Forbidden and <code>Action not permitted</code> error.</li></ul><h2 id="upload-media-to-an-album" tabindex="-1">Upload media to an album <a class="header-anchor" href="#upload-media-to-an-album" aria-label="Permalink to “Upload media to an album”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>New media is added at the start of the album&#39;s <code>content</code>. Uploading a photo byte-identical to one already in the album adds nothing and returns the existing <code>contentId</code>.</p><p>A newly uploaded video is transcoded before it is ready: until then its album item has <code>statusId</code> <code>3</code> and <code>processing</code> <code>true</code>, see <a href="/grindr-api/messaging/albums#get-album-media-processing-status">Get album media processing status</a>. Video bytes the server has already transcoded come back ready (<code>statusId</code> <code>1</code>) immediately. A video the transcoder cannot handle keeps <code>processing</code> <code>true</code> indefinitely.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v1/albums/{albumId}/content</span></span></code></pre></div><p>Query (optional):</p><ul><li><code>width</code> — integer, not validated and doesn&#39;t affect the stored media, videos get <code>400</code> without it, optional</li><li><code>height</code> — integer, not validated and doesn&#39;t affect the stored media, videos get <code>400</code> without it, optional</li><li><code>isFresh</code> — boolean, effect unknown, WIP, optional</li></ul><p>Body:</p><p>Content-Type: <code>multipart/form-data</code></p><ul><li><code>content</code> — binary</li></ul><p>Response:</p><ul><li><code>contentId</code> — long integer</li><li><code>contentUrl</code> — string or <code>null</code>, <code>null</code> for photo and video uploads</li></ul><p>Errors:</p><ul><li><code>400</code> — A video was uploaded without <code>width</code> or <code>height</code>.</li><li><code>402</code> — The album already holds <code>maxContentItemsPerAlbum</code> photos, or the upload is a video and the album already holds <code>maxVideosPerAlbum</code> videos, see <a href="/grindr-api/messaging/albums#get-album-limits">Get album limits</a>. The check runs before photo de-duplication, so a duplicate photo gets <code>402</code> too. A video that is still processing does not count toward <code>maxVideosPerAlbum</code>. Empty body.</li><li><code>413</code> — The whole <code>multipart/form-data</code> request body is larger than <code>maxContentSize</code>, see <a href="/grindr-api/messaging/albums#get-album-limits">Get album limits</a>. Empty body.</li></ul><h2 id="reorder-media-in-an-album" tabindex="-1">Reorder media in an album <a class="header-anchor" href="#reorder-media-in-an-album" aria-label="Permalink to “Reorder media in an album”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v1/albums/{albumId}/content/order</span></span></code></pre></div><p>Body:</p><ul><li><code>contentIds</code> — array of long integers, each Media file ID must appear exactly once</li></ul><p>Errors:</p><ul><li><code>400</code> — <code>contentIds</code> doesn&#39;t list every media file in the album.</li></ul><h2 id="delete-media-from-an-album" tabindex="-1">Delete media from an album <a class="header-anchor" href="#delete-media-from-an-album" aria-label="Permalink to “Delete media from an album”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Technically, this does not delete the media from CDN. All signed URLs will continue to work until expired. Uploading the same photo again assigns it the same <code>contentId</code>, uploading the same video again assigns a new one.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DELETE /v1/albums/{albumId}/content/{contentId}</span></span></code></pre></div><p>Response:</p><p>Empty</p><p>Errors:</p><ul><li><code>400</code> — The media is still processing (<code>processing</code> is <code>true</code>). Empty body.</li></ul><h2 id="get-album-media-processing-status" tabindex="-1">Get album media processing status <a class="header-anchor" href="#get-album-media-processing-status" aria-label="Permalink to “Get album media processing status”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v1/albums/{albumId}/content/{contentId}/processing</span></span></code></pre></div><p>Response:</p><ul><li><code>processing</code> — boolean, <code>true</code> while a video is being transcoded, always <code>false</code> for photos</li></ul><h2 id="pics-wip" tabindex="-1">Pics, WIP <a class="header-anchor" href="#pics-wip" aria-label="Permalink to “Pics, WIP”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This endpoint hasn&#39;t been researched yet</p></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v1/pics/limited/status</span></span></code></pre></div><p>Response:</p><ul><li><code>available</code> — integer</li><li><code>total</code> — integer</li></ul><h2 id="pics-expiring-wip" tabindex="-1">Pics expiring, WIP <a class="header-anchor" href="#pics-expiring-wip" aria-label="Permalink to “Pics expiring, WIP”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This endpoint hasn&#39;t been researched yet</p></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v4/pics/expiring</span></span></code></pre></div><h2 id="pics-expiring-status-wip" tabindex="-1">Pics expiring status, WIP <a class="header-anchor" href="#pics-expiring-status-wip" aria-label="Permalink to “Pics expiring status, WIP”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This endpoint hasn&#39;t been researched yet</p></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v4/pics/expiring/status</span></span></code></pre></div><h2 id="videos-expiring-status-wip" tabindex="-1">Videos expiring status, WIP <a class="header-anchor" href="#videos-expiring-status-wip" aria-label="Permalink to “Videos expiring status, WIP”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This endpoint hasn&#39;t been researched yet</p></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v4/videos/expiring/status</span></span></code></pre></div><h2 id="get-album-shares" tabindex="-1">Get album shares <a class="header-anchor" href="#get-album-shares" aria-label="Permalink to “Get album shares”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Returns profiles the album was shared with.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v1/albums/{albumId}/shares</span></span></code></pre></div><p>Response:</p><ul><li><code>profileIds</code> — array of integers</li></ul><h2 id="share-an-album" tabindex="-1">Share an album <a class="header-anchor" href="#share-an-album" aria-label="Permalink to “Share an album”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Automatically sends the shared album to chat with all listed profiles.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v4/albums/{albumId}/shares</span></span></code></pre></div><p>Body:</p><ul><li><code>profiles</code> — array of objects <ul><li><code>expirationType</code> — <a href="/grindr-api/messaging/albums#albumexpirationtype">AlbumExpirationType</a></li><li><code>profileId</code> — integer</li></ul></li></ul><p>Response:</p><p>Empty</p><h2 id="unshare-an-album" tabindex="-1">Unshare an album <a class="header-anchor" href="#unshare-an-album" aria-label="Permalink to “Unshare an album”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PUT /v1/albums/{albumId}/unshares</span></span></code></pre></div><p>Body:</p><ul><li><code>profiles</code> — array of objects <ul><li><code>profileId</code> — long integer</li><li><code>shareId</code> — string, not validated, the official client sends a random UUID v4</li></ul></li></ul><p>Response:</p><p>Empty</p><h2 id="unshare-an-album-from-everybody-wip" tabindex="-1">Unshare an album from everybody, WIP <a class="header-anchor" href="#unshare-an-album-from-everybody-wip" aria-label="Permalink to “Unshare an album from everybody, WIP”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This endpoint hasn&#39;t been researched yet</p></div><p>Unknown, returns 403</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PUT /v1/albums/{albumId}/shares/remove</span></span></code></pre></div><h2 id="add-drawer-media-to-an-album" tabindex="-1">Add drawer media to an album <a class="header-anchor" href="#add-drawer-media-to-an-album" aria-label="Permalink to “Add drawer media to an album”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Copies media from the <a href="/grindr-api/messaging/drawer#get-media-in-drawer">drawer</a> into the album. <code>ids</code> are drawer media ids. A video id results in <code>400</code>, even within <code>maxVideoLength</code>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v1/albums/{albumId}/content/chat/list-by-id</span></span></code></pre></div><p>Query:</p><ul><li><code>isFresh</code> — boolean</li></ul><p>Body:</p><ul><li><code>ids</code> — array of long integers</li></ul><p>Response:</p><p>Empty.</p><p>Errors:</p><ul><li><code>402</code> — The album is full. Unlike <a href="/grindr-api/messaging/albums#upload-media-to-an-album">Upload media to an album</a>, its video counts toward <code>maxContentItemsPerAlbum</code>. Empty body.</li></ul><h2 id="get-album-limits" tabindex="-1">Get album limits <a class="header-anchor" href="#get-album-limits" aria-label="Permalink to “Get album limits”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Interestingly, /v2/albums/storage appears to exist, though it is not used in the current version of the APK.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v1/albums/storage</span></span></code></pre></div><p>Response:</p><ul><li><code>subscriptionType</code> — string, e.g. <code>FreeAlbums</code></li><li><code>maxAlbums</code> — integer</li><li><code>maxContentItemsPerAlbum</code> — integer, photos per album, videos don&#39;t count</li><li><code>maxShares</code> — integer</li><li><code>maxViewableAlbums</code> — integer</li><li><code>maxViewableVideos</code> — integer</li><li><code>maxContentSize</code> — long integer, size in bytes of the whole upload request body</li><li><code>maxContentSizeHumanReadable</code> — string, incorrectly uses decimal multiples notation (MB) when it in fact calculates binary notation (MiB), so API&#39;s <code>120.00 MB</code> is actually 120 MiB or 125.8291 MB</li><li><code>maxVideoLength</code> — long integer, length in milliseconds (1/1000th of a second), not enforced by the server</li><li><code>minVideoLength</code> — long integer, length in milliseconds (1/1000th of a second)</li><li><code>maxShareableAlbums</code> — integer</li><li><code>maxVideosPerAlbum</code> — integer, videos per album, counted separately from <code>maxContentItemsPerAlbum</code>, so a full album holds <code>maxContentItemsPerAlbum</code> photos plus <code>maxVideosPerAlbum</code> videos</li></ul><h2 id="albums-red-dot-wip" tabindex="-1">Albums red dot, WIP <a class="header-anchor" href="#albums-red-dot-wip" aria-label="Permalink to “Albums red dot, WIP”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This endpoint hasn&#39;t been researched yet</p></div><p>This may just be tracking but could also be related to something else</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PUT /v1/albums/red-dot</span></span></code></pre></div><p>Response:</p><p>Empty.</p><h2 id="gets-albums-shared-with-us" tabindex="-1">Gets albums shared with us <a class="header-anchor" href="#gets-albums-shared-with-us" aria-label="Permalink to “Gets albums shared with us”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v3/pressie-albums/feed</span></span></code></pre></div><p>Body (optional):</p><ul><li><code>isFavorite</code> — boolean, optional, only albums shared by <a href="/grindr-api/users/favorites">favorite</a> users</li><li><code>isOnline</code> — boolean, optional, only albums shared by currently online users</li><li><code>onlyVideo</code> — boolean, optional, only albums with at least one video</li><li><code>blur</code> — boolean, optional, blur media urls in response</li></ul><p>Response:</p><ul><li><code>profileFeeds</code> — array of objects <ul><li><code>profileId</code> — integer</li><li><code>paywallStatus</code> — string, <code>ALLOW</code> or <code>PAYWALL</code> (locked)</li><li><code>seen</code> — boolean</li><li><code>content</code> — object</li><li><code>profile</code> — <a href="/grindr-api/messaging/albums#pressieprofilemini">PressieProfileMini</a></li></ul></li><li><code>sharedAlbums</code> — array of objects <ul><li><em>everything from <a href="/grindr-api/messaging/albums#albumpreview">AlbumPreview</a></em></li><li><code>albumViewable</code> — boolean</li><li><code>albumVersion</code> — integer</li><li><code>expiresAt</code> — unix timestamp in milliseconds or <code>null</code></li><li><code>name</code> — string or <code>null</code></li><li><code>ownerProfileId</code> — integer</li><li><code>imageCount</code> — integer</li><li><code>videoCount</code> — integer</li><li><code>coverContent</code> — object <ul><li><code>id</code> — long integer</li><li><code>contentType</code> — string</li><li><code>location</code> — string, cover media location/URL</li><li><code>status</code> — string</li></ul></li><li><code>profile</code> — <a href="/grindr-api/messaging/albums#pressieprofilemini">PressieProfileMini</a></li></ul></li><li><code>experimentStatus</code> — integer or <code>null</code></li><li><code>nonEmptyPersonalAlbumCount</code> — integer</li><li><code>emptyAlbumId</code> — long integer or <code>null</code></li></ul><h2 id="get-previews-of-locked-albums-shared-with-us" tabindex="-1">Get previews of locked albums shared with us <a class="header-anchor" href="#get-previews-of-locked-albums-shared-with-us" aria-label="Permalink to “Get previews of locked albums shared with us”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v3/pressie-albums/feed/paywall/</span></span></code></pre></div><p>Body (optional):</p><ul><li><code>counterpartyId</code> — long integer, profile ID or <code>null</code></li></ul><p>Response:</p><ul><li><code>albumPaywallContent</code> — array of objects <ul><li><code>albumId</code> — long integer</li><li><code>profile</code> — <a href="/grindr-api/messaging/albums#pressieprofilemini">PressieProfileMini</a></li><li><code>paywallCoverUrl</code> — see <a href="/grindr-api/media/signed-cdn-files">Media -&gt; Signed CDN files</a></li><li><code>paywallUrls</code> — see <a href="/grindr-api/media/signed-cdn-files">Media -&gt; Signed CDN files</a></li><li><code>albumsItemCount</code> — integer</li></ul></li></ul><h2 id="pressie-albums-feed-profile-id-wip" tabindex="-1">Pressie albums feed profile ID, WIP <a class="header-anchor" href="#pressie-albums-feed-profile-id-wip" aria-label="Permalink to “Pressie albums feed profile ID, WIP”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This endpoint hasn&#39;t been researched yet</p></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v3/pressie-albums/feed/{profileId}</span></span></code></pre></div><h2 id="pressie-albums-feed-update-read-wip" tabindex="-1">Pressie albums feed update read, WIP <a class="header-anchor" href="#pressie-albums-feed-update-read-wip" aria-label="Permalink to “Pressie albums feed update read, WIP”">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This endpoint hasn&#39;t been researched yet</p></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v3/pressie-albums/feed/update/read</span></span></code></pre></div><h2 id="gets-fresh-albums-shared-with-us" tabindex="-1">Gets fresh albums shared with us <a class="header-anchor" href="#gets-fresh-albums-shared-with-us" aria-label="Permalink to “Gets fresh albums shared with us”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v3/pressie-albums/fresh-feed</span></span></code></pre></div><p>Body:</p><ul><li><code>isFavorite</code> — boolean, optional, only albums shared by <a href="/grindr-api/users/favorites">favorite</a> users</li><li><code>isOnline</code> — boolean, optional, only albums shared by currently online users</li><li><code>onlyVideo</code> — boolean, optional, only albums with at least one video</li><li><code>blur</code> — boolean, optional, blur media urls in response</li></ul><p>Response:</p><ul><li><code>profileFeeds</code> — array of objects <ul><li><code>profileId</code> — integer</li><li><code>paywallStatus</code> — string, <code>ALLOW</code> or <code>PAYWALL</code> (locked)</li><li><code>seen</code> — boolean</li><li><code>content</code> — object</li><li><code>profile</code> — <a href="/grindr-api/messaging/albums#pressieprofilemini">PressieProfileMini</a></li></ul></li><li><code>sharedAlbums</code> — array of objects <ul><li><em>everything from <a href="/grindr-api/messaging/albums#albumpreview">AlbumPreview</a></em></li><li><code>albumViewable</code> — boolean</li><li><code>albumVersion</code> — integer</li><li><code>expiresAt</code> — unix timestamp in milliseconds or <code>null</code></li><li><code>name</code> — string or <code>null</code></li><li><code>ownerProfileId</code> — integer</li><li><code>imageCount</code> — integer</li><li><code>videoCount</code> — integer</li><li><code>coverContent</code> — object <ul><li><code>id</code> — long integer</li><li><code>contentType</code> — string</li><li><code>location</code> — string, cover media location/URL</li><li><code>status</code> — string</li></ul></li><li><code>profile</code> — <a href="/grindr-api/messaging/albums#pressieprofilemini">PressieProfileMini</a></li></ul></li><li><code>experimentStatus</code> — integer or <code>null</code></li><li><code>nonEmptyPersonalAlbumCount</code> — integer</li><li><code>emptyAlbumId</code> — long integer or <code>null</code></li></ul><h2 id="albumexpirationtype" tabindex="-1">AlbumExpirationType <a class="header-anchor" href="#albumexpirationtype" aria-label="Permalink to “AlbumExpirationType”">​</a></h2><p>Album expiration type.</p><p>Previously shared <a href="/grindr-api/messaging/messages#albummessagebody">albums in chat</a> inherit new <code>expirationType</code> settings from newer sharings of the album.</p><ul><li><code>&quot;INDEFINITE&quot;</code> or <code>0</code> — &quot;Indefinitely&quot;</li><li><code>&quot;ONCE&quot;</code> or <code>1</code> — &quot;View Once&quot;, limited by 30 minutes from request</li><li><code>&quot;TEN_MINUTES&quot;</code> or <code>2</code> — &quot;For 10 Minutes&quot;</li><li><code>&quot;ONE_HOUR&quot;</code> or <code>3</code> — &quot;For 60 Minutes&quot;</li><li><code>&quot;ONE_DAY&quot;</code> or <code>4</code> — &quot;For 24 Hours&quot;</li></ul><h2 id="albumpreview" tabindex="-1">AlbumPreview <a class="header-anchor" href="#albumpreview" aria-label="Permalink to “AlbumPreview”">​</a></h2><ul><li><code>albumId</code> — long integer</li><li><code>albumNumber</code> — integer or <code>null</code> if album has expired or was locked</li><li><code>totalAlbumsShared</code> — integer or <code>null</code> if album has expired or was locked</li><li><code>hasUnseenContent</code> — boolean</li></ul><h2 id="albummin" tabindex="-1">AlbumMin <a class="header-anchor" href="#albummin" aria-label="Permalink to “AlbumMin”">​</a></h2><ul><li><em>everything from <a href="/grindr-api/messaging/albums#albumpreview">AlbumPreview</a></em></li><li><code>albumName</code> — string, appears to always be <code>null</code></li><li><code>profileId</code> — integer</li><li><code>albumViewable</code> — boolean</li></ul><h2 id="albumdetails" tabindex="-1">AlbumDetails <a class="header-anchor" href="#albumdetails" aria-label="Permalink to “AlbumDetails”">​</a></h2><ul><li><code>sharedCount</code> — integer</li><li><code>createdAt</code> — string, date formatted as ISO 8601, e.g. <code>2026-03-27T20:39:00</code></li><li><code>updatedAt</code> — string, date formatted as ISO 8601, e.g. <code>2026-03-27T20:39:00</code></li></ul><h2 id="albumexpiration" tabindex="-1">AlbumExpiration <a class="header-anchor" href="#albumexpiration" aria-label="Permalink to “AlbumExpiration”">​</a></h2><ul><li><code>expiresAt</code> — unix timestamp in milliseconds or <code>null</code></li><li><code>expirationType</code> — <a href="/grindr-api/messaging/albums#albumexpirationtype">AlbumExpirationType</a> or <code>null</code></li></ul><h2 id="albumcontentmin" tabindex="-1">AlbumContentMin <a class="header-anchor" href="#albumcontentmin" aria-label="Permalink to “AlbumContentMin”">​</a></h2><ul><li><code>contentId</code> — long integer</li><li><code>contentType</code> — string</li><li><code>coverUrl</code> — <a href="/grindr-api/messaging/albums#albumcoverurl">AlbumCoverUrl</a></li><li><code>statusId</code> — integer, <code>1</code> ready, <code>3</code> processing, other values unknown</li></ul><h2 id="albumcontent" tabindex="-1">AlbumContent <a class="header-anchor" href="#albumcontent" aria-label="Permalink to “AlbumContent”">​</a></h2><ul><li><em>everything from <a href="/grindr-api/messaging/albums#albumcontentmin">AlbumContentMin</a></em></li><li><code>thumbUrl</code> — string, unblurred preview, see <a href="/grindr-api/media/signed-cdn-files">Media -&gt; Signed CDN files</a></li><li><code>url</code> — string, original file, see <a href="/grindr-api/media/signed-cdn-files">Media -&gt; Signed CDN files</a>, may be <code>&quot;&quot;</code> if <code>remainingViews</code> is 0</li><li><code>processing</code> — boolean, <code>true</code> while the server transcodes an uploaded video; <code>statusId</code> is then <code>3</code>, and <code>coverUrl</code>, <code>thumbUrl</code> and <code>url</code> all equal the placeholder <code>https://d3w4wp6rol9nvz.cloudfront.net/https://d1weu1y74qn7ma.cloudfront.net/albums-video-loading.mp4</code></li><li><code>rejectionId</code> — unknown or <code>null</code></li></ul><h2 id="myalbum" tabindex="-1">MyAlbum <a class="header-anchor" href="#myalbum" aria-label="Permalink to “MyAlbum”">​</a></h2><ul><li><em>everything from <a href="/grindr-api/messaging/albums#albumdetails">AlbumDetails</a></em></li><li><code>albumId</code> — long integer</li><li><code>albumName</code> — see <a href="/grindr-api/messaging/albums#album-name">Album name</a> or <code>null</code></li><li><code>profileId</code> — integer</li><li><code>version</code> — integer</li><li><code>content</code> — array of <a href="/grindr-api/messaging/albums#albumcontentwithhash">AlbumContentWithHash</a></li><li><code>isShareable</code> — boolean</li></ul><h2 id="albumcontentwithhash" tabindex="-1">AlbumContentWithHash <a class="header-anchor" href="#albumcontentwithhash" aria-label="Permalink to “AlbumContentWithHash”">​</a></h2><ul><li><em>everything from <a href="/grindr-api/messaging/albums#albumcontent">AlbumContent</a></em></li><li><code>contentHash</code> — string, lowercase hex SHA-256 of the uploaded bytes, optional</li></ul><h2 id="albumcontentwithremainingviews" tabindex="-1">AlbumContentWithRemainingViews <a class="header-anchor" href="#albumcontentwithremainingviews" aria-label="Permalink to “AlbumContentWithRemainingViews”">​</a></h2><ul><li><em>everything from <a href="/grindr-api/messaging/albums#albumcontent">AlbumContent</a></em></li><li><code>remainingViews</code> — integer, might be -1; absent if this is your own album, optional</li></ul><h2 id="albumdetailsresponse" tabindex="-1">AlbumDetailsResponse <a class="header-anchor" href="#albumdetailsresponse" aria-label="Permalink to “AlbumDetailsResponse”">​</a></h2><ul><li><em>everything from <a href="/grindr-api/messaging/albums#albummin">AlbumMin</a></em></li><li><em>everything from <a href="/grindr-api/messaging/albums#albumdetails">AlbumDetails</a></em></li><li><code>content</code> — array of <a href="/grindr-api/messaging/albums#albumcontentwithremainingviews">AlbumContentWithRemainingViews</a></li><li><code>isShareable</code> — boolean</li><li><code>contentCount</code> — object or <code>null</code>, optional <ul><li><code>imageCount</code> — integer</li><li><code>videoCount</code> — integer</li></ul></li></ul><h2 id="albumshareinfo" tabindex="-1">AlbumShareInfo <a class="header-anchor" href="#albumshareinfo" aria-label="Permalink to “AlbumShareInfo”">​</a></h2><ul><li><code>profileId</code> — long integer</li><li><code>hasAlbum</code> — boolean</li><li><code>hasSharedWithMe</code> — boolean</li></ul><h2 id="albumssharedbyprofileresponse" tabindex="-1">AlbumsSharedByProfileResponse <a class="header-anchor" href="#albumssharedbyprofileresponse" aria-label="Permalink to “AlbumsSharedByProfileResponse”">​</a></h2><ul><li><code>albums</code> — array of objects <ul><li><em>everything from <a href="/grindr-api/messaging/albums#albummin">AlbumMin</a></em></li><li><em>everything from <a href="/grindr-api/messaging/albums#albumexpiration">AlbumExpiration</a></em></li><li><code>profileId</code> — integer</li><li><code>content</code> — <a href="/grindr-api/messaging/albums#albumcontentmin">AlbumContentMin</a>, a single blurred preview content item</li><li><code>contentCount</code> — object <ul><li><code>imageCount</code> — integer</li><li><code>videoCount</code> — integer</li></ul></li></ul></li></ul><h2 id="album-name" tabindex="-1">Album name <a class="header-anchor" href="#album-name" aria-label="Permalink to “Album name”">​</a></h2><p>String, may be empty (<code>&quot;&quot;</code>) or <code>null</code>, non-string values are coerced into strings.</p><p>Maximum length: 255 UTF-8 bytes, which is 255 characters for ASCII strings (1 ASCII character is encoded as 1 byte) but less if you include emojis or non-ascii characters (2+ bytes/one codepoint).</p><ul><li><code>albumName</code> — string or <code>null</code></li></ul><h2 id="albumrenameresponse" tabindex="-1">AlbumRenameResponse <a class="header-anchor" href="#albumrenameresponse" aria-label="Permalink to “AlbumRenameResponse”">​</a></h2><ul><li><code>albumId</code> — integer</li><li><code>albumName</code> — string or <code>null</code></li></ul><h2 id="albumsharerequest" tabindex="-1">AlbumShareRequest <a class="header-anchor" href="#albumsharerequest" aria-label="Permalink to “AlbumShareRequest”">​</a></h2><ul><li><code>profiles</code> — array of objects <ul><li><code>expirationType</code> — <a href="/grindr-api/messaging/albums#albumexpirationtype">AlbumExpirationType</a></li><li><code>profileId</code> — integer</li></ul></li></ul><h2 id="albumunsharerequest" tabindex="-1">AlbumUnshareRequest <a class="header-anchor" href="#albumunsharerequest" aria-label="Permalink to “AlbumUnshareRequest”">​</a></h2><ul><li><code>profiles</code> — array of objects <ul><li><code>profileId</code> — long integer</li><li><code>shareId</code> — string, not validated, the official client sends a random UUID v4</li></ul></li></ul><h2 id="albumcontentuploadresponse" tabindex="-1">AlbumContentUploadResponse <a class="header-anchor" href="#albumcontentuploadresponse" aria-label="Permalink to “AlbumContentUploadResponse”">​</a></h2><ul><li><code>contentId</code> — long integer</li><li><code>contentUrl</code> — string or <code>null</code>, <code>null</code> for photo and video uploads</li></ul><h2 id="albumcontentprocessingresponse" tabindex="-1">AlbumContentProcessingResponse <a class="header-anchor" href="#albumcontentprocessingresponse" aria-label="Permalink to “AlbumContentProcessingResponse”">​</a></h2><ul><li><code>processing</code> — boolean, <code>true</code> while a video is being transcoded, always <code>false</code> for photos</li></ul><h2 id="albumstoragelimits" tabindex="-1">AlbumStorageLimits <a class="header-anchor" href="#albumstoragelimits" aria-label="Permalink to “AlbumStorageLimits”">​</a></h2><ul><li><code>subscriptionType</code> — string, e.g. <code>FreeAlbums</code></li><li><code>maxAlbums</code> — integer</li><li><code>maxContentItemsPerAlbum</code> — integer, photos per album, videos don&#39;t count</li><li><code>maxShares</code> — integer</li><li><code>maxViewableAlbums</code> — integer</li><li><code>maxViewableVideos</code> — integer</li><li><code>maxContentSize</code> — long integer, size in bytes of the whole upload request body</li><li><code>maxContentSizeHumanReadable</code> — string, incorrectly uses decimal multiples notation (MB) when it in fact calculates binary notation (MiB), so API&#39;s <code>120.00 MB</code> is actually 120 MiB or 125.8291 MB</li><li><code>maxVideoLength</code> — long integer, length in milliseconds (1/1000th of a second), not enforced by the server</li><li><code>minVideoLength</code> — long integer, length in milliseconds (1/1000th of a second)</li><li><code>maxShareableAlbums</code> — integer</li><li><code>maxVideosPerAlbum</code> — integer, videos per album, counted separately from <code>maxContentItemsPerAlbum</code>, so a full album holds <code>maxContentItemsPerAlbum</code> photos plus <code>maxVideosPerAlbum</code> videos</li></ul><h2 id="pressieprofilemini" tabindex="-1">PressieProfileMini <a class="header-anchor" href="#pressieprofilemini" aria-label="Permalink to “PressieProfileMini”">​</a></h2><ul><li><code>profileId</code> — long integer, optional</li><li><code>name</code> — string, optional</li><li><code>profileUrl</code> — string or <code>null</code>, optional</li><li><code>onlineUntil</code> — unix timestamp in milliseconds or <code>null</code>, optional</li><li><code>distanceKm</code> — number or <code>null</code>, optional</li></ul><h2 id="pressiealbumsfeedresponse" tabindex="-1">PressieAlbumsFeedResponse <a class="header-anchor" href="#pressiealbumsfeedresponse" aria-label="Permalink to “PressieAlbumsFeedResponse”">​</a></h2><ul><li><code>profileFeeds</code> — array of objects <ul><li><code>profileId</code> — integer</li><li><code>paywallStatus</code> — string, <code>ALLOW</code> or <code>PAYWALL</code> (locked)</li><li><code>seen</code> — boolean</li><li><code>content</code> — object</li><li><code>profile</code> — <a href="/grindr-api/messaging/albums#pressieprofilemini">PressieProfileMini</a></li></ul></li><li><code>sharedAlbums</code> — array of objects <ul><li><em>everything from <a href="/grindr-api/messaging/albums#albumpreview">AlbumPreview</a></em></li><li><code>albumViewable</code> — boolean</li><li><code>albumVersion</code> — integer</li><li><code>expiresAt</code> — unix timestamp in milliseconds or <code>null</code></li><li><code>name</code> — string or <code>null</code></li><li><code>ownerProfileId</code> — integer</li><li><code>imageCount</code> — integer</li><li><code>videoCount</code> — integer</li><li><code>coverContent</code> — object <ul><li><code>id</code> — long integer</li><li><code>contentType</code> — string</li><li><code>location</code> — string, cover media location/URL</li><li><code>status</code> — string</li></ul></li><li><code>profile</code> — <a href="/grindr-api/messaging/albums#pressieprofilemini">PressieProfileMini</a></li></ul></li><li><code>experimentStatus</code> — integer or <code>null</code>, optional</li><li><code>nonEmptyPersonalAlbumCount</code> — integer</li><li><code>emptyAlbumId</code> — long integer or <code>null</code>, optional</li></ul><h2 id="pressiealbumspaywallresponse" tabindex="-1">PressieAlbumsPaywallResponse <a class="header-anchor" href="#pressiealbumspaywallresponse" aria-label="Permalink to “PressieAlbumsPaywallResponse”">​</a></h2><ul><li><code>albumPaywallContent</code> — array of objects <ul><li><code>albumId</code> — long integer</li><li><code>profile</code> — <a href="/grindr-api/messaging/albums#pressieprofilemini">PressieProfileMini</a></li><li><code>paywallCoverUrl</code> — see <a href="/grindr-api/media/signed-cdn-files">Media -&gt; Signed CDN files</a></li><li><code>paywallUrls</code> — see <a href="/grindr-api/media/signed-cdn-files">Media -&gt; Signed CDN files</a></li><li><code>albumsItemCount</code> — integer</li></ul></li></ul><h2 id="albumcoverurl" tabindex="-1">AlbumCoverUrl <a class="header-anchor" href="#albumcoverurl" aria-label="Permalink to “AlbumCoverUrl”">​</a></h2><p>String with URL or <code>null</code>, blurred downscaled preview.</p><p>JPEG photo with the first frame of video in case of video files.</p><p>Becomes unavailable (<code>AccessDenied</code>) after album has expired.</p><p>See <a href="/grindr-api/media/signed-cdn-files">Media -&gt; Signed CDN files</a>.</p>',244)])])}const b=i(s,[["render",t]]);export{p as __pageData,b as default};
